-- VFDA VA Quiz App - Call practice database changes (new tables only: practice calls, cadence standards, settings, pilot offices).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after practice-days.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261126120000_call_practice.sql =====

-- Call practice: voice roleplay calls with an AI patient (src/lib/call-practice/).
-- Replaces the separate VA Call Trainer 2.0 app.
--
-- Only NEW tables. Nothing the quizzes use is altered: no quiz table, rule
-- slot, office rule, scenario, schedule or unlock is changed here. Call
-- practice reads office rules; it never writes them.
--
--   practice_calls          one practice call (transcript, result, feedback)
--   call_cadence_standards  VFDA's scheduling cadence standards, used when an
--                           office has no accepted rule for that cadence item.
--                           Kept apart from rule_slots.suggested_answer on
--                           purpose: the quiz scenario builder reads that
--                           column, and these standards must not change quizzes.
--   call_practice_settings  one row: global on/off, daily cap, who gets it
--   call_practice_offices   offices with Call practice turned on (the pilot)
--
-- Writes to practice_calls happen only on the server (service role) after the
-- route checks the signed-in user, so a VA can never edit a transcript or a
-- result. Reads follow the quiz results pattern: VFDA admins see everything,
-- a doctor sees their office's calls, a VA sees only their own.
--
-- Safe to run more than once.

-- ---------------------------------------------------------------------------
-- Settings (one row)
-- ---------------------------------------------------------------------------
create table if not exists public.call_practice_settings (
  id                  boolean primary key default true check (id),
  enabled             boolean not null default true,   -- global off switch
  daily_cap           integer not null default 15 check (daily_cap between 1 and 100),
  -- false: only offices listed in call_practice_offices (the pilot).
  -- true: every office.
  all_offices         boolean not null default false,
  -- true: only VAs whose role includes Phones (an empty role list means every role).
  require_phones_role boolean not null default false,
  updated_by          uuid references public.profiles (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

insert into public.call_practice_settings (id) values (true) on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
-- Offices with Call practice turned on
-- ---------------------------------------------------------------------------
create table if not exists public.call_practice_offices (
  office_id  uuid primary key references public.offices (id) on delete cascade,
  enabled_by uuid references public.profiles (id) on delete set null,
  enabled_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- VFDA cadence standards
-- ---------------------------------------------------------------------------
create table if not exists public.call_cadence_standards (
  rule_key   text primary key,             -- the matching rule slot key, e.g. ROF_RULE
  label      text not null,                -- "Report of findings"
  checks     text not null,                -- what the call checks
  standard   text not null,                -- VFDA's standard
  -- Care plan: the patient doesn't push for it and the VA passes by deferring
  -- it to the office visit. Other items: the patient's requests test the rule.
  call_use   text not null default 'test' check (call_use in ('test', 'defer')),
  sort_order integer not null default 0,
  updated_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

insert into public.call_cadence_standards (rule_key, label, checks, standard, call_use, sort_order) values
  ('CARE_PLAN_CADENCE', 'Care plan cadence',
   'That the VA leaves the care plan for the office visit instead of setting it on the phone',
   'Care plan usually isn''t discussed on inbound phone calls; it''s usually discussed in the office. The patient should not push for a care plan, and the VA passes by deferring it to the visit.',
   'defer', 1),
  ('ROF_RULE', 'Report of findings',
   'How soon after Day 1, which time blocks',
   'Next business day after Day 1, at the latest 2 business days; only in the doctor''s report-of-findings blocks.',
   'test', 2),
  ('SCHEDULE_MATRIX', 'Scheduling matrix',
   'Visit types, length, provider, allowed times',
   'New patient: 1-hour block. Report of findings: 1-hour block. Adjustment: 10-15 min. Re-exam: 30 min every 12 visits. New patients only in new-patient slots.',
   'test', 3),
  ('PROTECTED_BLOCKS', 'Protected blocks',
   'Times never booked (lunch, admin, doctor-only)',
   'Nothing booked in the doctor''s lunch or admin blocks; no new patients in the last 30 min before close.',
   'test', 4),
  ('PROVIDER_RULES', 'Provider rules',
   'Which provider sees which visit type',
   'Day 1, report of findings and re-exams with the doctor only; regular visits with any adjusting provider.',
   'test', 5),
  ('LATE_CANCEL_RULE', 'Late cancel',
   'Notice required, what happens if late',
   '24 hours'' notice. Under 24 hours: rebook in the same week and log it; a second late cancel in 30 days goes to the doctor.',
   'test', 6),
  ('CONFIRM_RULE', 'Confirmations',
   'Confirmation timing',
   'Confirm by text the day before, by 3 p.m.; call anyone unconfirmed.',
   'test', 7),
  ('NO_SHOW_RULE', 'No-shows',
   'No-show follow-up',
   'Call within 15 minutes, voicemail + text, offer to rebook, flag a second miss.',
   'test', 8),
  ('SAME_DAY_CUTOFF', 'Same-day cutoff',
   'Same-day booking',
   'Until 2 hours before close, then the doctor approves.',
   'test', 9)
on conflict (rule_key) do nothing;   -- never overwrite a standard VFDA has edited

-- ---------------------------------------------------------------------------
-- Practice calls
-- ---------------------------------------------------------------------------
create table if not exists public.practice_calls (
  id               uuid primary key default gen_random_uuid(),
  va_id            uuid not null references public.profiles (id) on delete cascade,
  office_id        uuid not null references public.offices (id) on delete cascade,
  call_type        text not null check (call_type in ('easy', 'challenging', 'w2d1_roleplay', 'w2d2_roleplay')),
  -- Which required roleplay (W2D1: new_patient, existing_patient, confirmation;
  -- W2D2: financial_objection, upset_scheduling, safety_privacy). Null for easy / challenging.
  roleplay         text check (roleplay in ('new_patient', 'existing_patient', 'confirmation',
                                            'financial_objection', 'upset_scheduling', 'safety_privacy')),
  persona          jsonb not null default '{}',   -- the made-up patient
  persona_summary  text,                          -- rolling summary, keeps patient prompts small
  transcript       jsonb not null default '[]',   -- [{speaker: 'va' | 'patient', text, at}]
  patient_turns    integer not null default 0,
  status           text not null default 'in_progress' check (status in ('in_progress', 'finished', 'abandoned')),
  result           text check (result in ('passed', 'practice_again')),
  checklist        jsonb,                         -- [{item, met, note, source?}]
  feedback         jsonb,                         -- {went_well: [], try_next: []}
  cadence_sources  jsonb not null default '{}',   -- {RULE_KEY: 'office' | 'vfda_standard'}
  flags            jsonb not null default '[]',   -- e.g. [{kind: 'possible_real_data', quote}]
  usage            jsonb not null default '{}',   -- token / character counts, for cost tracking
  overridden_by    uuid references public.profiles (id) on delete set null,
  override_result  text check (override_result in ('passed', 'practice_again')),
  override_note    text,
  overridden_at    timestamptz,
  started_at       timestamptz not null default now(),
  finished_at      timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint practice_calls_roleplay_matches check (
    (call_type in ('easy', 'challenging') and roleplay is null)
    or (call_type = 'w2d1_roleplay' and roleplay in ('new_patient', 'existing_patient', 'confirmation'))
    or (call_type = 'w2d2_roleplay' and roleplay in ('financial_objection', 'upset_scheduling', 'safety_privacy'))
  ),
  constraint practice_calls_finished_has_time check (status <> 'finished' or finished_at is not null),
  constraint practice_calls_override_complete check (
    (override_result is null and overridden_by is null and overridden_at is null)
    or (override_result is not null and overridden_at is not null)
  ),
  constraint practice_calls_size check (
    octet_length(transcript::text) + octet_length(coalesce(persona_summary, '')) <= 200000
  )
);

create index if not exists practice_calls_va_started on public.practice_calls (va_id, started_at desc);
create index if not exists practice_calls_office_started on public.practice_calls (office_id, started_at desc);

-- updated_at
do $$
declare t text;
begin
  foreach t in array array['call_practice_settings', 'call_cadence_standards', 'practice_calls'] loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format(
      'create trigger set_updated_at before update on public.%I for each row execute function private.set_updated_at()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------
alter table public.call_practice_settings enable row level security;
alter table public.call_practice_offices enable row level security;
alter table public.call_cadence_standards enable row level security;
alter table public.practice_calls enable row level security;

-- Settings: VFDA manages; anyone signed in may read (the on/off switch and cap).
drop policy if exists "admin manages call practice settings" on public.call_practice_settings;
create policy "admin manages call practice settings" on public.call_practice_settings
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

drop policy if exists "signed in reads call practice settings" on public.call_practice_settings;
create policy "signed in reads call practice settings" on public.call_practice_settings
  for select to authenticated
  using (true);

-- Offices turned on: VFDA manages; a doctor or VA reads their own office's row.
drop policy if exists "admin manages call practice offices" on public.call_practice_offices;
create policy "admin manages call practice offices" on public.call_practice_offices
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

drop policy if exists "member reads own call practice office" on public.call_practice_offices;
create policy "member reads own call practice office" on public.call_practice_offices
  for select to authenticated
  using (office_id = (select private.my_office_id()));

-- Cadence standards: VFDA manages; doctors read them (they appear in feedback).
drop policy if exists "admin manages cadence standards" on public.call_cadence_standards;
create policy "admin manages cadence standards" on public.call_cadence_standards
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

drop policy if exists "doctor reads cadence standards" on public.call_cadence_standards;
create policy "doctor reads cadence standards" on public.call_cadence_standards
  for select to authenticated
  using ((select private.my_role()) = 'doctor');

-- Calls: VFDA everything; doctor reads their office; VA reads their own.
-- No insert / update / delete for doctors or VAs: the server writes calls.
drop policy if exists "admin full access" on public.practice_calls;
create policy "admin full access" on public.practice_calls
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

drop policy if exists "doctor reads own office calls" on public.practice_calls;
create policy "doctor reads own office calls" on public.practice_calls
  for select to authenticated
  using (private.is_doctor_of_office(office_id));

drop policy if exists "va reads own calls" on public.practice_calls;
create policy "va reads own calls" on public.practice_calls
  for select to authenticated
  using (va_id = (select auth.uid()) and (select private.my_role()) = 'va');

-- ---------------------------------------------------------------------------
-- Pilot offices: Lenahan, Coremedix, Sleppy (matched by name)
-- ---------------------------------------------------------------------------
do $$
declare
  pilot text;
  found integer;
begin
  foreach pilot in array array['lenahan', 'coremedix', 'sleppy'] loop
    insert into public.call_practice_offices (office_id)
    select o.id from public.offices o
    where o.name ilike '%' || pilot || '%'
    on conflict (office_id) do nothing;
    select count(*) into found from public.offices o where o.name ilike '%' || pilot || '%';
    if found <> 1 then
      raise notice 'Call practice pilot: % office(s) match "%". Check call_practice_offices.', found, pilot;
    end if;
  end loop;
end $$;

commit;
